def extract_range(start: int, end: int, what: str) -> str:
    """Lines [start, end] inclusive joined by newlines; sanity-balance braces."""
    block = "\n".join(lines[start:end + 1])
    if block.count("{") != block.count("}"):
        raise RuntimeError(f"unbalanced braces in {what} (lines {start}..{end})")
    return block


def capture_doc(above_line_idx: int) -> list:
    """Consecutive `///` doc-comment lines immediately above `above_line_idx`."""
    doc = []
    i = above_line_idx
    while i >= 0 and lines[i].lstrip().startswith("///"):
        doc.append(lines[i])
        i -= 1
    doc.reverse()
    return doc


def prepend_doc(block: str, above_line_idx: int) -> str:
    doc = capture_doc(above_line_idx)
    if not doc:
        return block
    return "\n".join(doc + [block])


def add_pub_crate(text: str, indent: str) -> str:
    """Add `pub(crate) ` to the first non-doc `fn` line at `indent`."""
    parts = text.split("\n")
    for j, ln in enumerate(parts):
        if ln.lstrip().startswith("///"):
            continue
        assert re.match(rf"^{re.escape(indent)}(pub )?fn \w+", ln), repr(ln)
        if ln.startswith(f"{indent}pub fn"):
            return text
        parts[j] = ln.replace(f"{indent}fn ", f"{indent}pub(crate) fn ", 1)
        return "\n".join(parts)
    raise RuntimeError("no fn line")

