    /// Behavior changes between MATLAB versions.
    BehaviorChanges,
    /// Configuration file validation.
    ConfigurationIssues,
}

impl Category {
    /// Returns the string identifier used in `.mlt.toml` config files.
    pub fn as_str(&self) -> &'static str {
